  'settings.connections.edit': 'Змінити це з’єднання',
  'settings.connections.type': 'Тип',
  'settings.connections.typeHint': '«Немає» і «Пряме» означають різне. «Немає» бездіяльне: воно не називає жодного з’єднання й ніколи не використовується, тож існує лише доти, доки ви не заповните рядок до кінця. «Пряме» — справжній вибір: трафік іде через власне з’єднання цієї машини в обхід будь-якого проксі для перелічених нижче хостів. Так NAS виводять з-під проксі, що діє на весь застосунок. Рядок, чий фільтр збігається з хостом, перемагає рядок без фільтра, тож прямий рядок із фільтром завжди бере гору над проксі, що ловить усе.',
