  'settings.connections.passwordHint': 'Збережений пароль ніколи не надсилається на цю сторінку, тому поле порожнє. Залиште його порожнім — і збережений залишиться. Збережений пароль не переїжджає з рядком на інший хост, порт чи тип: зміните одне з них — і його доведеться задати знову.',
  'settings.connections.filter': 'Фільтр хостів',
