  'settings.rules.var.match': 'Група захоплення N взірця «збігається зі взірцем» цього правила на полі FIELD. Це <jd:source:N> з JDownloader під іменем, що каже, який взірець він читає. Правило без відповідного взірця на цьому полі відхиляється під час збереження, а не створює мовчки теку з іменем <jd:match:url:1>.',
  'settings.rules.var.append': 'Нічого при першій появі цього значення, далі _2, _3 і так далі',
  'settings.rules.sourceDivergence': 'Копіюєте шаблон із конфігурації JDownloader? <jd:source:N> тут означає інше: сегмент шляху URL-джерела, а не групу захоплення. Значення JD записується як <jd:match:FIELD:N>. Ці два варіанти збігаються достатньо часто, щоб це було небезпечно, тож скопійований шаблон варто прогнати вхолосту нижче, перш ніж зберігати.',

  'settings.rules.testTitle': 'Перевірити на посиланні',
