  'settings.reconnect.method.script': 'Скрипт',
  'settings.reconnect.offState': 'Перепідключення вимкнено. Ніхто не просить у роутера нової адреси, а ліміт хостера лишається на розсуд звичайної паузи між спробами.',

  'settings.reconnect.command': 'Програма',
  'settings.reconnect.commandHint': 'Повний шлях до програми, яку буде запущено. Вона стартує напряму, а не через оболонку, тож конвеєру, перенаправленню чи двом командам поспіль місце у способі «Скрипт». %%router%%, %%username%%, %%password%% та %%ip%% підставляються перед запуском.',
  'settings.reconnect.args': 'Аргументи',
  'settings.reconnect.argsHint': 'По одному в рядку, щоб аргумент із пробілом лишився одним аргументом. Тут підставляються ті самі чотири змінні.',

  'settings.reconnect.upnpState': 'Більше нічого не потрібно. Шлюз знаходять, опитуючи мережу, тож цей спосіб працює, не знаючи нічого про роутер.',
  'settings.reconnect.upnpLocation': 'URL опису шлюзу',
  'settings.reconnect.upnpLocationHint': 'Необов’язково і зазвичай порожнє. Заповнюйте лише там, де багатоадресний пошук відфільтровано, а сам шлюз чудово доступний: самим лише виявленням цього не полагодити.',

  'settings.reconnect.interpreter': 'Інтерпретатор',
  'settings.reconnect.interpreterHint': 'Програма, якій передається скрипт, із повним шляхом: /bin/sh, /bin/bash, /usr/bin/python3.',
  'settings.reconnect.interpreterArgs': 'Аргументи інтерпретатора',
  'settings.reconnect.interpreterArgsHint': 'По одному в рядку, ставляться перед файлом скрипта. Зазвичай порожнє.',
  'settings.reconnect.script': 'Скрипт',
  'settings.reconnect.scriptHint': 'Записується в закритий тимчасовий файл, а інтерпретатор отримує шлях до нього, тож ніщо звідси ніколи не потрапляє в лапках у командний рядок. Змінні підставляються до запису файлу, а отже пароль, набраний у цьому полі, опиниться в тому файлі: %%password%% лишає його в полі пароля.',

  'settings.reconnect.router': 'Адреса роутера',
  'settings.reconnect.routerHint': 'Роутер у вашій власній мережі, без схеми: 192.168.1.1, а не http://192.168.1.1/. Саме в це розгортається %%router%%. Це не публічна адреса, і плутати їх не можна нізащо: запит входу, спрямований на публічну, відправить пароль вашого роутера в інтернет.',
  'settings.reconnect.routerFind': 'Знайти мій роутер',
  'settings.reconnect.routerFinding': 'Пошук…',
  'settings.reconnect.routerFound': 'Знайдено {address}.',
