  'settings.reconnect.routerFailed': 'Тут не вдалося прочитати адресу роутера: {reason}',
  'settings.reconnect.username': 'Ім’я користувача роутера',
  'settings.reconnect.usernameHint': 'Вхід до роутера, а не обліковий запис у хостера. Саме в це розгортається %%username%%.',
  'settings.reconnect.password': 'Пароль роутера',
  'settings.reconnect.passwordStored': 'збережено і сюди ніколи не повертається',
  'settings.reconnect.passwordHint': 'Збережений пароль ніколи не надсилається назад на цю сторінку, тому поле порожнє: лишіть його порожнім, і збережений збережеться далі. Наберіть новий, щоб замінити його. Щоб прибрати пароль зовсім, наберіть будь-що, а потім знову очистіть поле.',

  'settings.reconnect.requests': 'Запити',
  'settings.reconnect.requestsHint': 'Відтворюються по черзі, і прогін спиняється на першому, на який роутер не відповів. Це метод LiveHeader із JDownloader: зазвичай вхід, а тоді перезавантаження чи розрив зв’язку. Змінні приймає будь-яке поле.',
  'settings.reconnect.requestsEmpty': 'Запитів поки що немає. Додайте один або вставте записаний скрипт.',
