  'settings.reconnect.requestRemove': 'Вилучити цей запит',
  'settings.reconnect.requestMethod': 'Метод',
  'settings.reconnect.requestUrl': 'URL',
  'settings.reconnect.requestUrlHint': 'Уся URL-адреса, разом зі схемою. http://%%router%%/login.cgi має звичний вигляд.',
  'settings.reconnect.requestHeaders': 'Заголовки',
  'settings.reconnect.requestHeadersHint': 'По одному в рядку, у вигляді Ім’я: значення. Заголовок Host враховується і справді йде в мережу, а це саме те, що потрібно прошивкам роутерів, які віддають адмінку через віртуальний хост.',
  'settings.reconnect.requestBody': 'Тіло',
  'settings.reconnect.requestBodyHint': 'Надсилається як є. Тіло без власного типу вмісту йде як надсилання форми, а записаний вхід до роутера саме ним і є.',

  'settings.reconnect.import': 'Імпорт скрипта',
  'settings.reconnect.importLabel': 'Скрипт LiveHeader або curl',
  'settings.reconnect.importHint': 'Вставте скрипт перепідключення з JDownloader, разом із маркерами. Його змінні перекладаються на вході, а %%%routerip%%% стає адресою роутера, а не публічною, бо тут це дві різні речі.',
  'settings.reconnect.importRead': 'Прочитати скрипт',
  'settings.reconnect.importReading': 'Читання…',
  'settings.reconnect.importClose': 'Закрити',
  'settings.reconnect.importMapped': 'розпізнано: {n}',
  'settings.reconnect.importRefusedCount': 'відхилено: {n}',
  'settings.reconnect.importUse': 'Замінити список на {n}',
  'settings.reconnect.importLine': 'Рядок {n}',
  'settings.reconnect.importBlocked': 'Зі скрипта, де є відхилений рядок, не береться нічого. Половина скрипта роутера - це вхід без перезавантаження, і виринає таке аж за кілька днів, у вигляді адреси, яка ніколи не змінюється.',
  'settings.reconnect.importFailed': 'Скрипт не вдалося прочитати: {reason}',

  'settings.reconnect.checkTitle': 'Перевірка адреси',
  'settings.reconnect.checkUrl': 'URL для перевірки IP',
  'settings.reconnect.checkUrlHint': 'Запитується перед запуском способу і ще раз після нього; прогін вважається завершеним, щойно видана адреса зміниться. Типового значення немає: менеджер завантажень, який ви розгорнули в себе, не повинен починати повідомляти вашу адресу службі, якої ви ніколи не обирали. Видавати треба адресу, яку бачить інтернет, бо сторінка, що повертає адресу з вашої власної мережі, не відрізнить перепідключення від прогону, який нічого не змінив.',
  'settings.reconnect.checkPresets': 'Відомі служби',
  'settings.reconnect.checkPresetsHint': 'Швидкий вибір для тих, кому байдуже, а не значення за замовчуванням: жодну з них не обрано за вас, і будь-яка сторінка, що показує вашу публічну адресу, підійде так само добре.',
  'settings.reconnect.interval': 'Секунд між перевірками (від 1 до 60)',
  'settings.reconnect.intervalHint': 'Скільки чекати між двома зверненнями до адреси перевірки після того, як спосіб відпрацював. Нижня межа є тому, що цикл без неї перетворює службу перевірки на мішень.',
  'settings.reconnect.timeout': 'Скільки секунд перевіряти далі (від 5 до 900)',
  'settings.reconnect.timeoutHint': 'How long to keep looking before the run is called a failure. A reconnect still waiting a quarter of an hour later has failed whatever this says. A timeout below the interval is raised to it, or the run would be over before a single check happened. The Command and Script methods give their program the same number of seconds to finish before the checking starts; one still running then is stopped, and the run fails.',
  'settings.reconnect.clamped': 'Збережено як {n}.',

  'settings.reconnect.runTitle': 'Запустити просто зараз',
  'settings.reconnect.runNow': 'Перепідключитися зараз',
  'settings.reconnect.running': 'Виконується…',
  'settings.reconnect.runMoved': 'Адреса змінилася з {from} на {to}.',
  'settings.reconnect.runDetail': 'перевірок: {n}, {secs} с',
  'settings.reconnect.runBusy': 'Перепідключення вже виконується, тож це не запускалося. Результат належить тому, хто попросив про перше.',
  'settings.reconnect.runFailed': 'Перепідключення не дійшло до кінця: {reason}',
  'settings.reconnect.stateConfigured': 'Налаштовано',
  'settings.reconnect.stateNotConfigured': 'Не налаштовано',
  'settings.reconnect.stateIdle': 'Простоює',
