  'settings.reconnect.notReady': 'Не готово: {reason}',
  'settings.reconnect.reason.off': 'Перепідключення вимкнено',
  'settings.reconnect.reason.noCommand': 'Для методу «команда» не задано програму',
  'settings.reconnect.reason.noRequests': 'Для методу «запити» не задано жодного запиту',
  'settings.reconnect.reason.requestNoURL': 'Запит {n} не має URL',
  'settings.reconnect.reason.noInterpreter': 'Для методу «скрипт» не задано інтерпретатор',
  'settings.reconnect.reason.noScript': 'Для методу «скрипт» не задано сам скрипт',
  'settings.reconnect.reason.noCheckURL': 'Не задано URL для перевірки IP',
  'settings.reconnect.reason.unknownMethod': 'Невідомий метод «{method}»',
  'settings.reconnect.reason.noRouter': 'Скрипт використовує %%{var}%%, але адресу роутера не задано',
  'settings.reconnect.runUsesSaved': 'Запускається збережене, а не те, що на екрані. Спершу збережіть.',
  'settings.reconnect.policy': 'Коли це стається саме',
  'settings.reconnect.policyHint': 'Автоматичні перепідключення запускаються рівно в одному місці, і це не ця сторінка. Одне з них стартує, коли сам рушій завантаження просить про нову спробу після паузи: так хостер каже, що ліміт прив’язаний до цієї адреси. Воно ніколи не виконується при зупиненій черзі, бо перезавантаження роутера обриває завантаження, які ще тривають. Воно ніколи не виконується, поки перепідключення налаштоване не до кінця. Одночасно триває лише одне: другий запит чекає на вирок першого, замість того щоб битися з ним за роутер. А якщо адреса не змінюється, ніщо не пришвидшується і звичайна пауза між спробами добігає свого.',

  'shell.bar': 'Черга та рядок стану',
