  'settings.chunks': 'З’єднань на завантаження (0 = автоматично)',
  'settings.chunksHint': 'Скільки з’єднань відкриває одне завантаження, коли нічого конкретнішого не діє. Правило або окреме завантаження може назвати власне число і перебиває це. Хостер, який терпить менше, однаково отримає менше: обмеження хостера може число тільки знизити, ніколи не підняти. При 0 вирішує застосунок. Більше кількох з’єднань нічого не дає в хостера з обмеженням на файл і надійно призводить до позначення облікового запису.',
  'task.chunks': 'З’єднання (0 = загальне налаштування)',
  'task.chunksHint': 'Скільки з’єднань відкриває це одне завантаження. Воно перебиває загальне налаштування і будь-яке правило, яке його задало, але ніколи не хостера: хостер, який терпить менше, однаково отримає менше. При 0 виняток знімається і число знову вирішується не тут.',
  'columns.connection': 'З’єднання',

  'props.title': 'Властивості',
  'props.mixed': 'Кілька значень',
  'props.mixedHint': 'Ці рядки не збігаються, тому поле порожнє. Якщо його не чіпати, нічого не зміниться; впишіть щось, і кожен вибраний рядок отримає вписане.',
  'props.name': 'Ім’я',
  'props.nameHint': 'Одне ім’я файлу, ніколи не шлях: ім’я з / або \\ відхиляється. Завершене завантаження перейменовується і на диску, щоб список і тека не могли розходитися. Поточне зберігає файл, відкритий його бекендом, і отримує нове ім’я після завершення. Ще не розпочате отримує його одразу. Ім’я належить одному файлу, тому це поле пропонується лише для одного рядка.',
  'props.comment': 'Коментар',
  'props.commentHint': 'Твоя власна нотатка про це посилання. Вона зберігається і показується у списку; ніщо в застосунку за нею не діє.',
  'props.priority': 'Пріоритет',
  'props.priorityHint': 'Вищий іде першим. Це переставляє те, що ще чекає; завантаження, яке вже триває, назад у чергу не відправляється.',
  'props.autoExtract': 'Розпаковувати архіви',
  'props.autoExtractHint': 'Чи розпаковувати архів після завершення завантаження. «Успадкувати» лишає рішення сторінці налаштувань архівів, і це не те саме, що вимкнено. Перемикач читається в момент розпакування, тож увімкнувши його зараз, ти розпакуєш і те, що завершилося раніше.',
