  'accounts.debrid.emptyHint': 'Додай акаунт одного з підтримуваних debrid-сервісів, щоб посилання хостерів відкривалися автоматично.',
  'accounts.debrid.title': 'Акаунти debrid',
  'accounts.debrid.viaJD': 'через JDownloader',
  'accounts.debrid.hint': 'Debrid-сервіс — це один платний обліковий запис, який відкриває одразу багато файлохостингів. KnightLoader надсилає йому посилання й завантажує пряме посилання, яке отримує назад, на повній швидкості, без очікування й без капчі. Це рекомендований шлях, бо інакше потрібен окремий преміум-акаунт на кожному хостингу. Деякі сервіси доступні лише через вбудований JDownloader, і тоді вхід виконує він. У рядках таких сервісів це зазначено.',
