  'settings.help.intake.title': 'Додавання завантажень',
  'settings.help.intake.body':
    'Вставляйте посилання у збирач, по одному на рядок або безладним текстом. Пошук знаходить посилання, де б вони не стояли: посеред речення, по кілька в рядку чи розбиті поштовим клієнтом на два рядки.',
  'settings.help.intake.b1': 'Перетягніть файл-контейнер посилань (.dlc, .ccf, .rsdf) або звичайний список посилань.',
