  'settings.scripts.use': 'Увімкнути цей скрипт',
  'settings.scripts.code': 'Код',
  'settings.scripts.starter': '// Цей скрипт запускається під час події, вибраної вище.\n// log(...) пише рядок у «Вивід», а notify(message) надсилає сповіщення.\n// trigger і queue є завжди; task, pkg, extraction, reconnect,\n// account і captcha лише тоді, коли подія їх передає.\n',
  'settings.scripts.timeout': 'Обмеження часу',
  'settings.scripts.timeoutHint':
    'Як довго цей скрипт може виконуватися, перш ніж його зупинять. Від 100 мс до 30 с; 0 використовує типове значення 5000 мс.',
  'settings.scripts.timeoutUnit': 'мс',
