  'settings.access.phrase.statusHintOff': 'Реле не активне. Твої екземпляри доступні лише в локальній мережі.',
  'settings.access.phrase.statusHintLost': 'Немає зв’язку з реле. KnightLoader продовжує спроби. До того часу екземпляри бачать одне одного лише в локальній мережі.',
