  'settings.resolvers.moduleUnavailableHint': 'Усе нижче однаково зберігається й почне діяти, щойно yt-dlp стане доступним. Нічого з того, що ви зараз редагуєте, не втратиться.',
  'settings.resolvers.about': 'Налаштування бекенда yt-dlp, який забирає вміст із медіа- та стримінгових сайтів, що їх підтримує сам yt-dlp. Який сервіс узагалі обробляє те чи інше посилання (yt-dlp, акаунт debrid чи бекенд JDownloader), визначає порядок пріоритету на сторінці «Облікові записи». Тут задається, що робить yt-dlp, коли посилання вже передано йому.',
