    'The port this instance listens for swarm connections on. 0 lets the built-in torrent client pick one.',
  'settings.torrents.portRestartHint': 'Рушій створює свій торрент-клієнт лише один раз, тож новий порт почне діяти після перезапуску цього екземпляра. Попросити роутер пробросити його можна одразу, незалежно від того, чи вже слухає на ньому якийсь торрент.',
  'settings.torrents.portMapHint': 'Просить роутер пробросити вказаний вище порт на цю машину через UPnP, щоб піри за іншим роутером все одно могли його досягти. Не кожен роутер це підтримує, а деякі приймають запит, хоча насправді нічого не працює.',
