  'settings.torrents.portMapConfirmed': 'Підтверджено: порт {port} проброшено, доступність перевірено.',
  'settings.torrents.portMapUnconfirmed': 'Роутер прийняв запит, але не вдалося підтвердити, що проброс працює. Деякі роутери мовчки приймають запит і не застосовують його. Спробуйте перевірити доступність ззовні мережі.',
  'settings.torrents.portMapFailed': 'Не вдалося пробросити порт: {error}',
  'settings.torrents.portMapUnavailable': 'Ця збірка ще не підтримує проброс портів.',
  'settings.torrents.networkTitle': 'Пошук пірів',
