  'settings.torrents.dhtHint': 'Знаходить пірів без участі трекера, використовуючи інші BitTorrent-клієнти як розподілений довідник.',
  'settings.torrents.pex': 'Обмін пірами (PEX)',
  'settings.torrents.pexHint': 'Обмінюється відомими пірами з уже підключеними, щоб рій із малою кількістю пірів знаходився швидше.',
  'settings.torrents.privateNote': 'Приватний торрент автоматично вимикає обидва, щойно стають відомі його метадані, незалежно від того, що задано тут: одразу для завантаженого файлу .torrent або щойно власні метадані magnet-посилання надійдуть із рою. Більшість приватних трекерів банять облікові записи, що використовують будь-що з цього.',
  'container.noJD': 'він зашифрований, і відкрити його може лише бекенд JDownloader. Такого не налаштовано: вкажіть у KL_JD JDownloader, доступний цьому екземпляру, і перезапустіть екземпляр.',
