  'settings.torrents.notApplied': 'Два з налаштувань нижче ця збірка поки не застосовує. Ліміт віддавання зберігається й перевіряється, але рушій не може застосувати його до завантаження, що вже йде. До звичайного торрента не доходять і DHT та PEX: він роздає з обома ввімкненими, хоч би що тут було задано. З приватним торрентом інакше, як пояснює (i) біля розділу «Пошук пірів».',
  'onboarding.step': 'Крок {n} з {total}',
