  'onboarding.finish': 'Готово',
  'onboarding.welcome.title': 'Ласкаво просимо до KnightLoader',
  'onboarding.welcome.body': 'KnightLoader — це менеджер завантажень, який ви розгортаєте в себе. Вставте або перетягніть посилання, і його забере відповідний бекенд: вбудований рушій для простих посилань на файли, yt-dlp для медіасторінок, debrid-сервіс для хостерів, за які ви вже платите, або headless JDownloader для всього іншого. Цей короткий огляд показує єдине налаштування, яке варто перевірити перед початком.',
  'onboarding.welcome.langLabel': 'Мова інтерфейсу',
  'onboarding.folder.title': 'Куди мають потрапляти файли?',
  'onboarding.folder.body': 'Це тека, у яку записуються завершені завантаження. Введіть шлях або знайдіть теку на сервері. Змінити її можна будь-коли на сторінці налаштувань «Загальне».',
  'onboarding.accounts.title': 'Преміум-хостери, коли б ви не забажали',
  'onboarding.accounts.body': 'Черга працює й зовсім без облікових записів. Коли захочете повну швидкість на хостері чи debrid-сервісі, за який уже платите, додайте його логін у розділі «Облікові записи». Нічого з цього не треба налаштовувати зараз.',
  'onboarding.accounts.link': 'Відкрити «Облікові записи»',
  'onboarding.finished.title': 'Усе готово',
  'onboarding.finished.body': 'На цьому огляд закінчується. Сторінка «Довідка» в налаштуваннях містить повний опис усього іншого, що вміє ця версія, а більшість елементів керування мають власне пояснення за значком (i).',

