  'settings.feeds.seededHint': 'Перша перевірка нової підписки записує все, що стрічка несе в ту мить, і не додає з цього нічого, щоб на вас не впав увесь архів видавця одним махом. Додається лише те, що з’явиться після цього.',
  'settings.feeds.remembered': 'Запам’ятовано записів: {n}',
  'settings.feeds.rememberedHint': 'Скільки записів ця підписка впізнає знову, щоб вони не додалися вдруге, поки стрічка ще їх видає. Щонайбільше 500 на підписку. Першими випадають найстаріші, і запис, який ще стоїть у стрічці, серед них не буває ніколи.',
  'settings.feeds.test': 'Тест',
  'settings.feeds.testBusy': 'Отримання',
  'settings.feeds.testHint': 'Одноразово звертається до цієї адреси і показує, що в ній, щоб ви бачили заголовки, з якими звіряють ваш фільтр. Він лише читає: до збирача нічого не потрапляє і ніщо не записується як бачене, тож натиснути можна й для адреси, яку ви ще не зберегли.',
