  'settings.headerProfiles.title': 'Профілі HTTP-заголовків',
  'settings.headerProfiles.hint': 'Деякі сайти віддають файл лише браузеру, який увійшов, або лише тоді, коли звертання приходить з їхньої ж сторінки. Профіль зберігає заголовки для рівно одного сайту, зашифровані так само, як ваші ключі до облікових записів, і KnightLoader надсилає їх із кожним завантаженням із того сайту.',
  'settings.headerProfiles.empty': 'Профілів заголовків ще немає.',
  'settings.headerProfiles.emptyHint': 'Профіль варто завести, щойно завантаження працює лише доти, доки ви ввійшли в браузері.',
  'settings.headerProfiles.add': 'Додати профіль',
  'settings.headerProfiles.name': 'Назва профілю',
  'settings.headerProfiles.nameHint': 'Під цією назвою ви звертаєтесь до профілю, у правилі Packagizer так само, як тут. Лише літери, цифри та - _ чи .',
