  'settings.rules.action.category': 'Категорія',
  'settings.rules.action.categoryHint': 'Складає посилання, які підійшли, в одну з шухляд зі списку «Категорії» нижче на цій сторінці, а та приносить із собою власну теку, місце в черзі, перемикач розпакування і правило для файлу, який уже є. Якщо лишити як є, жодне правило про це не висловлюється, і посилання лишається без категорії. Якщо це правило називає ще й теку завантажень, перемагає та тека, а решту шухляда однаково постачає. Назвати видалену шухляду під час збереження не дадуть, бо правило, яке вказує на відсутню шухляду, для кожного підхожого посилання не робить геть нічого, і мовчки.',
  'settings.rules.action.categoryNone': 'Категорій ще немає. Спершу створіть одну нижче на цій сторінці, у розділі «Категорії», інакше це правило складало б посилання в шухляду, якої не існує.',
