  'detail.label': 'Деталі завдання',
  'detail.link': 'Посилання',
  'detail.address': 'Адреса',
  'detail.addressHint': 'Адреса, з якої запустили це завантаження. Про неї попросив застосунок, і це не завжди те місце, звідки прийшли байти: через дебрид-сервіс хостер нижче це сайт, на якому лежить файл, а бекенд це той, хто його забрав.',
  'detail.copy': 'Копіювати',
  'detail.copied': 'Скопійовано',
  'detail.copyFailed': 'Нічого не скопійовано.',
  'detail.origin': 'Надійшло через',
  'detail.originUnknown': 'Не записано',
  'detail.package': 'Пакет',
  'detail.noPackage': 'У жодному пакеті',
  'detail.onDisk': 'Зараз на диску',
  'detail.onDiskHint': 'Скільки файл важить на диску цієї секунди, запитано в сервера, а не пораховано тут. Завантаження, яке виконується, росте між одним поглядом і наступним, і це не той розмір, який оголосив хостер.',
  'detail.mirrorOf': 'Запасна копія',
  'detail.times': 'Часові позначки',
  'detail.timesHint': 'Коли це посилання надійшло, коли востаннє змінилося і коли завершилося. Часу, коли почалося передавання, тут немає: застосунок ніколи його не записував, а вгадане з трьох інших було б числом, за яким люди діють.',
  'detail.nextTry': 'Наступна спроба',
  'detail.stalledSince': 'Стоїть на місці з',
  'detail.retries': 'Повторів дотепер',
  'detail.retriesHint': 'Скільки разів це завантаження пробували знову після невдачі. Щойно завантаження завершується, лічильник скидається на нуль, тож готовий рядок показує нуль навіть тоді, коли знадобилося чотири заходи. Скільки спроб лишилося, тут не написано: стеля залежить від причини й від хостера, і ця сторінка порахувати її не може.',
  'detail.stallRestarts': 'Перезапусків після застою',
  'detail.stallRestartsHint': 'Скільки разів нагляд за застоєм сам перезапустив це завантаження. Скидається на нуль, щойно завантаження завершиться, так само як лічильник вище.',
  'detail.failure': 'Що пішло не так',
  'detail.cause': 'Причина',
  'detail.message': 'Що сказав бекенд',
  'detail.messageHint': 'Речення від того, що намагалося це забрати, слово в слово й без перекладу. Це поточна помилка й більше нічого: перезапуск її стирає, а попередні ніде не зберігаються.',
  'detail.heldBack': 'Утримує',
  'detail.doing': 'Робить зараз',
  'detail.gaveUp': 'Більше жодної спроби',
  'detail.gaveUpHint': 'Тут спинилися навмисно, а не тому, що скінчилися спроби: капча, повний диск або правило, яке для цього хостера каже «ніколи». Підняти кількість повторів тут нічого не змінить. Сама позначка в базу даних не пишеться, тож після перезапуску її немає, хоч причина, з якої вона з’явилася, нікуди не поділася.',
  'detail.rules': 'Правила, які це сформували',
  'detail.rulesHint': 'Правила, які спрацювали на це посилання під час підготовки, у тому порядку, у якому спрацювали. Вони зберігаються за назвою, тож перейменоване відтоді правило вже не знаходиться, а правило, яке ніколи не мало назви, зберігається з тією позицією, яку мало тоді. Клац по ньому відкриває його в редакторі правил.',
  'detail.openRule': 'Відкрити в редакторі правил',
  'detail.noRules': 'Жодне правило не торкнулося цього посилання.',
  'detail.player': 'Відтворення',
  'detail.play': 'Відтворити тут',
  'detail.playHint': 'Відтворює файл прямо з цього примірника, не завантажуючи його вдруге. Доки ви не натиснете «Відтворити», нічого не забирається, і файл лишається там, де він є.',
  'detail.playPartial': 'Це завантаження не завершене. Відтворити можна лише ту частину, що вже лежить на диску, перестрибнути далі не вийде, а деякі файли не відтворюють нічого, доки не буде останнього байта.',
  'detail.playUnsupported': 'Цей браузер не може відтворити цей файл. Відкрийте або збережіть його через меню правої кнопки миші.',
  'detail.playRemote': 'Тут відтворюються лише файли на цьому примірнику. Інший примірник віддає свої файли одним шматком і без перестрибування, а з таким плеєр не впорається.',
  'detail.playNotLocal': 'Це завантаження забрав JDownloader, тож файл лежить на диску того процесу, а не на цьому.',
  'detail.playNoFile': 'На диску ще немає чого відтворювати.',
