  'settings.rules.notFound': 'Тут немає правила з назвою «{name}». Його перейменували або видалили відтоді, як додали посилання, яке його називає.',

  'notifications.title': 'Сповіщення',
  'notifications.titleHint': 'Вирішіть для кожної події, чи з’явиться вона бульбашкою в застосунку, повідомленням від вашої операційної системи, чи не з’явиться взагалі. Системне повідомлення дійде до вас лише доки відкрита вкладка KnightLoader, а тихий режим нижче діє додатково.',
  'notifications.channel.app': 'У застосунку',
