  'notifications.channel.silent': 'Нічого не показувати',
  'notifications.event.downloadDone': 'Завантаження завершено',
  'notifications.event.downloadDoneHint': 'Кожне завантаження, яке дійшло до кінця, про це повідомляє. Двісті файлів у черзі означають двісті таких повідомлень, тож добре подумайте, перш ніж відправляти їх у систему.',
  'notifications.event.downloadFailed': 'Завантаження не вдалося',
  'notifications.event.downloadFailedHint': 'Завантаження, яке здалося. Тихий режим його не приховує ніколи.',
  'notifications.event.extractionDone': 'Розпакування завершено',
  'notifications.event.extractionDoneHint': 'Архів, який дорозпаковано. Раніше про це ніде не повідомлялося, тому спочатку стоїть «Нічого не показувати».',
  'notifications.event.extractionFailed': 'Розпакування не вдалося',
  'notifications.event.extractionFailedHint': 'Архів, який спинився, не дійшовши до кінця. Зазвичай бракує пароля, і файли лишаються на місці, доки ви цим не займетеся.',
  'notifications.event.captchaWaiting': 'Чекає капча',
  'notifications.event.captchaWaitingHint': 'Вікно капчі в цій вкладці відкриється так чи так. Спочатку стоїть «Нічого не показувати», бо це вікно і є повідомленням, доки ви на нього дивитеся. Поставте системне повідомлення, і капча у фоновій вкладці дійде до вас раніше, ніж хостер викине сеанс.',
  'notifications.event.captchaFailed': 'Капча не вдалася',
  'notifications.event.captchaFailedHint': 'Ніхто не відповів вчасно, або відповідь не дійшла. Завантаження за нею лишається на місці.',
  'notifications.event.captchaResolved': 'Капчу розв’язано деінде',
  'notifications.event.captchaResolvedHint': 'Хтось в іншому браузері або автоматичний розв’язувач відповів на неї, і вікно закрилося саме.',
  'notifications.systemUnavailable': 'Системних повідомлень тут немає: браузер пропонує їх лише через HTTPS або на localhost. Усе з цієї картки однаково показується в застосунку.',
  'notifications.systemBlocked': 'Браузер блокує сповіщення для цієї адреси. Рядки, поставлені на «Системне повідомлення», натомість показуються в застосунку, доки ви знову не дозволите їх у налаштуваннях сайту у своєму браузері.',
  'notifications.systemNotGranted': 'Браузер не дав дозволу, тож ця подія лишається в застосунку. Виберіть «Системне повідомлення» ще раз, щоб запитати знову.',
