  'volume.unsizedHint': 'У {n} з цих завантажень хостер так і не назвав розміру. Вони не додають до суми нічого, тож справжнє число більше за намальоване.',
  'volume.trimmedHint': 'Історія на своїй власній межі, тож усе, що старше за її найдавніший запис, у цій кривій теж відсутнє. Підніміть межу історії на цій сторінці, якщо хочете довший запис.',
  'volume.meter': 'Обсяг',
  'volume.meterHint': 'Скільки завантажено відтоді, як лічильник востаннє почав заново, у порівнянні з лімітом на сторінці налаштувань «Завантаження». Число змінюється, коли завантаження завершується, а не поки воно триває. Воно складається з історії завантажень, тож очищення історії обнуляє й цей лічильник.',
