  'settings.diagnostics.fileProblemHint': 'Перевірте, чи {path} існує і чи акаунт, під яким працює цей процес, може там писати. На Unraid це зазвичай означає, що тека належить root, а контейнер працює як інший користувач. Більше нічого не стало: останні {n} рядків і далі лежать у пам’яті і далі потрапляють у пакет діагностики.',
