  'settings.diagnostics.fileDownload': 'Завантажити',
  'settings.diagnostics.logSearch': 'Шукати в рядках',
  'settings.diagnostics.logSearchHint': 'Звичайний текст, без символів підстановки, великі й малі літери однакові. Шукає в рядках, завантажених тут, а не в старіших файлах. Щоб пошукати по цілому файлу, завантажте його.',
  'settings.diagnostics.logSource': 'Джерело',
  'settings.diagnostics.logSourceAll': 'Усі джерела',
  'settings.diagnostics.logSourceOther': 'Решта рядків',
  'settings.diagnostics.logSourceHint': 'З якої частини застосунку прийшов рядок, прочитано з початку самого рядка. Рядок, який не називає частини, стоїть під «Решта рядків». Фільтрувати за рівнем важливості немає чого: у цьому застосунку його не записує жодний рядок.',
  'settings.diagnostics.logFollow': 'Слідувати за новими рядками',
  'settings.diagnostics.logFollowHint': 'Кожні дві секунди питає, що додалося з минулого разу, і стрибає до найновішого рядка. Вимкнене лишає вигляд на місці, щоб під час читання нічого не з’їжджало.',
