  'detail.log.title': 'Журнал цього завантаження',
  'detail.log.hint': 'Рядки, які цей екземпляр записав і які називають це завантаження за його ідентифікатором.',
  'detail.log.empty': 'До цього завантаження нічого не записано.',
  'detail.log.emptyHint': 'Не кожен рядок фіксує, до якого завантаження він належить, тож завантаження може мати клопіт, а тут не з’явиться ні рядка. Увесь журнал стоїть на сторінці «Діагностика».',
  'detail.log.openDiagnostics': 'Відкрити увесь журнал',
  'detail.log.remote': 'Журнал лишається на тому екземплярі, який його написав. Для завантаження, що йде на іншій машині, тут тому нічого показати.',
  'settings.owner.identityTitle': 'Як хто пише цей екземпляр',
  'settings.owner.identityHint': 'Кожен файл, який створює цей екземпляр, отримує цього власника і ці права, і все, що він запускає, теж: yt-dlp, ffmpeg і вкладений JDownloader. У контейнері особа встановлена в ту мить, коли контейнер стартує, її задає акаунт, під яким його запустили, і з цієї сторінки змінити її не можна.',
  'settings.owner.uid': 'Користувач',
  'settings.owner.gid': 'Група',
  'settings.owner.umask': 'Umask',
  'settings.owner.umaskUnknown': 'Це ядро її не повідомляє',
  'settings.owner.asked': 'Бажано',
  'settings.owner.envIgnored': '{name}={value} задано, але цю змінну ніхто в цьому образі не читає. Особу задає акаунт, під яким запустили контейнер, а це {owner}.',
  'settings.owner.envHow': 'Якщо ви хочете працювати під іншим акаунтом, назвіть його в команді запуску: --user <uid>:<gid>. На Unraid це йде в Extra Parameters, і щоб це подіяло, контейнер треба створити наново.',
  'settings.owner.desktopNote': 'Десктопний застосунок працює під вашим власним акаунтом. PUID, PGID і UMASK це налаштування контейнера, і тут вони нічого не роблять.',
  'settings.owner.noOwners': 'На цій системі файли не мають власників, тож порівнювати нема чого. Це не несправність.',
  'settings.owner.checkTitle': 'Перевірка тек',
  'settings.owner.checkHint': 'Тут справді записують один файл і одну підтеку в кожну теку, потім дивляться, кому вони належать і хто ще може їх прочитати, і обидві прибирають назад. Це треба виміряти, а не вирахувати: спільний ресурс може мати власні правила прав, а тека з поставленим set-group-id видає іншу групу, ніж має цей процес. Перевірка запускається сама після того, як ви збережете змінену теку, і щоразу, коли ви натискаєте кнопку.',
  'settings.owner.run': 'Перевірити теки зараз',
  'settings.owner.running': 'Перевірка…',
  'settings.owner.never': 'Ще не перевірено.',
  'settings.owner.checkedAt': 'Остання перевірка {time}.',
  'settings.owner.checkFailed': 'Перевірка не змогла виконатися: {error}',
  'settings.owner.role.downloads': 'Тека завантажень',
  'settings.owner.role.work': 'Робоча тека',
  'settings.owner.role.category': 'Тека категорії',
  'settings.owner.role.watch': 'Тека під наглядом',
  'settings.owner.v.ok': 'Файли потрапляють сюди як {fileOwner} з {fileMode}, нові підтеки з {subdirMode}, а сама тека належить {dirOwner}. Нічого незвичного в цьому немає.',
  'settings.owner.v.ownerMismatch': 'Файли потрапляють сюди як {fileOwner}, а тека належить {dirOwner}. Читати їх зазвичай ще виходить, а перейменувати, перенести чи видалити з іншого акаунта ні, і все, що чекає, що тека володіє своїм вмістом, вважає ці файли чужими.',
  'settings.owner.v.groupUnreadable': 'Файли потрапляють сюди з {fileMode}, тож відкрити їх може лише {fileOwner}. Те, що працює під іншим акаунтом, бачить назви і більше нічого.',
  'settings.owner.v.dirUnreadable': 'Нові підтеки потрапляють сюди з {subdirMode}. Усередину не заходить ніхто, крім {fileOwner}, хоч би що дозволяли файли в них, а кожне завантаження потрапляє саме в таку підтеку.',
  'settings.owner.v.notWritable': 'Цей екземпляр тут узагалі не може писати: {detail}',
