  'settings.owner.v.unknown': 'На цій системі файли не мають власників, тож порівнювати тут нема чого. Це не несправність.',
  'settings.owner.fix.user': 'Запустіть контейнер під тим акаунтом, якому належить тека: --user {dirUid}:{dirGid} у команді запуску. На Unraid це йде в Extra Parameters.',
  'settings.owner.fix.chown': 'Або натомість передайте теку, на хості: chown -R {uid}:{gid} {dir}',
  'settings.owner.fix.mask': 'Цього цей екземпляр змінити не може. Маска приходить від того, що запустило контейнер, а вмонтований спільний ресурс може накинути власну через опцію umask, file_mode чи dir_mode. Виправляйте це там, де теку вмонтовано.',
  'settings.owner.fix.recreate': 'Змінена команда запуску потребує наново створеного контейнера. Перезапуску не досить: особа встановлена в ту мить, коли він стартує.',
  'settings.owner.fix.past': 'Уже завантажені файли зберігають того власника, з яким їх записали. Усе, що ви зміните, діє на те, що буде далі, а для решти потрібна команда вище.',
  'settings.selftest.title': 'Самоперевірка',
