  'settings.selftest.jd.provisioningOff': 'Автоматичне розгортання бекенда вимкнено, і адресу не задано, тож підключатися нема до чого.',
  'settings.selftest.jd.missing': 'Адресу бекенда не задано. Зашифровані DLC і посилання на контейнери відхиляються.',
  'settings.selftest.jd.missingAdvice': 'Ця збірка під час завантаження зазвичай запускає власний JDownloader без інтерфейсу і сама вписує KL_JD. Те, що змінна порожня, означає: цей запуск не вдався. Пошукайте в журналі нижче «JD provisioning failed», або задайте в KL_JD власний JDownloader.',
