  'settings.selftest.folders.noMark': 'На {dir} вільно {free}. Фіксованого порогу ви не задали, тож черга стримує завантаження лише тоді, коли воно і так уже не вміститься.',
  'settings.selftest.folders.unknown': 'На цій платформі не можна спитати, скільки місця на {dir}.',
  'settings.selftest.accounts': 'Дані входу до debrid',
  'settings.selftest.accounts.none': 'Жодного акаунта debrid не налаштовано, тож перевіряти було нічого.',
  'settings.selftest.accounts.allOk': 'Прийнято всі дані входу: {n}.',
  'settings.selftest.accounts.someFailed': 'Відхилених даних входу: {bad} з {n}.',
