  'settings.downloads.keepAwakeHint': 'Поки триває завантаження, а також поки його потім перевіряють, розпаковують, переносять або передають програмі подій, комп’ютер не засинає. Завантаження, яке чекає на наступну спробу, теж рахується. Екран однаково може вимкнутися. Щойно все це скінчиться, комп’ютер знову засинає як зазвичай.',
  'settings.transfer.incompleteEventPrograms': 'командні рядки програм подій',
  'settings.eventPrograms.argsHint': 'По одному в рядку. Кожен рядок доходить до програми як один аргумент із підставленими заповнювачами, і жодна оболонка його не читає: ім’я файлу з $( ) чи ; надходить саме з цими символами. Файл .bat чи .cmd отримує кожен аргумент у лапках, тож читайте його там як "%~1". Якщо програма це оболонка, замість заповнювачів використовуйте змінні середовища, у подвійних лапках, наприклад "$KL_FILE", щоб оболонка не могла прочитати ім’я файлу як команду.',
  'settings.eventPrograms.envHint': 'Кожен запуск отримує їх, порожні там, де подія нічого для них не має. KL_FILE це файл завантаження, а KL_FOLDER тека, у якій він лежить. Для готового пакета KL_FOLDER це тека, куди потрапила більшість його файлів; для розпакованого архіву тека, у яку його розпаковано. Невдале розпакування теж запускає програму, з KL_EXTRACT_OK зі значенням false. Якщо ви використовуєте робочу теку, готове завантаження чи пакет чекає, доки його файли перенесуть із неї, щонайбільше 15 хвилин. Власні налаштування KL_ цього екземпляра, зокрема ключі сервісів, ніколи не передаються.',
  'settings.eventPrograms.timeoutHint': 'Скільки може тривати один запуск, перш ніж його зупинять, від 5 до 3600 секунд. Усе, що запустила програма, зупиняється разом із нею.',
