  'settings.torrents.includeFiles': 'Лише ці файли',
  'settings.torrents.includeFilesHint': 'По одному регулярному виразу в рядку, звіряється зі шляхом файлу всередині торрента, як «збігається зі взірцем» у правилі Packagizer. Файл має збігтися з одним із них, щоб його завантажили. Регістр має значення; почніть взірець із (?i), щоб його ігнорувати.',
