  'collector.filtered.heldSummary': '{n} link(s) rejected',
  'collector.filtered.heldInfo': 'Links a link filter rule rejected, and torrents that announce a banned tracker. They are kept here instead of in the list above, so a working filter does not leave the collector looking full of junk. Nothing was lost. Restore puts a link back and lets it past the rule or ban that caught it, for when that turned out to be too broad. Clear deletes it. Either way, no file has been downloaded.',
  'collector.filtered.toastHeldBack': 'Staged {n} link(s); {held} rejected',
  'collector.filtered.toastAllHeldBack': 'Nothing was staged: {held} link(s) rejected',
  'settings.torrents.filesHint': 'Визначає, які файли торрента завантажуються, коли ніхто не вибрав їх вручну. Для magnet-посилання це стається, щойно надійде його список файлів. Файл .torrent відкриває свій список файлів із уже позначеним цим вибором, і він діє, якщо ви додасте торрент без змін. Те, що ви самі позначите чи знімете, завжди перемагає. Якби нічого не лишилося, завантажуються всі файли. Категорія може натомість мати власний вибір файлів.',
  'settings.torrents.extraTrackersHint': 'По одній адресі трекера в рядку, вони додаються до торрентів, щоб ті знаходили більше пірів. Файл .torrent, позначений як приватний, ніколи їх не отримує. Magnet-посилання повідомляє, чи воно приватне, лише коли надійде його список файлів, а тоді трекери вже додано, тож їх не отримує й magnet, чия власна адреса трекера містить passkey. Приватний трекер, який розпізнає вас за IP-адресою, а не за passkey, так виявити не можна: залиште це поле порожнім, якщо отримуєте magnet-посилання з такого трекера.',
  'settings.torrents.bannedTrackersHint':
    'One host name or tracker address per line; its subdomains count too. A torrent that announces to one of them is not added: it is rejected with the reason and waits in the collector beside the links the link filter rejected. Restoring it there lets it past the line that caught it, not past one you add later. A banned tracker is never added as an extra tracker either.',
