  'settings.categories.torrentFilesHint': 'Які файли торрента, віднесеного сюди, завантажуються, коли ніхто не позначив їх вручну. «Успадкувати» використовує вибір файлів зі сторінки «Торренти». «Власний» замінює його для цієї категорії, наприклад для музичної категорії, де саме дрібні файли і є альбомом. Він діє під час запуску торрента, тож охоплює й торрент, який сюди відніс правило Packagizer. Файли, які ви позначите самі, завжди перемагають.',
