  'accounts.routing.orderHintTorrents': 'Magnet links and .torrent files go either to the built-in torrent client or to a debrid service that takes torrents, whichever is higher in the list.',
  'accounts.routing.tip.torrent': 'Вбудований торрент-клієнт. Якщо над цим рядком стоїть debrid-сервіс, що приймає торренти, magnet-посилання й файли .torrent замість нього отримує він.',
  'settings.torrents.debridTitle': 'Через debrid-сервіс',
  'settings.torrents.debridHint':
    'TorBox, Real-Debrid, AllDebrid, Premiumize.me and Debrid-Link can fetch magnet links and .torrent files instead of the built-in torrent client. The service downloads the torrent to its own servers, and KnightLoader then fetches the files from there like any other link. Nothing seeds from this machine and your address never appears in a swarm, so no port needs to be open. A torrent the service already has is ready at once. The priority order on the Accounts page decides whether a debrid service or the built-in torrent client goes first. A torrent from a private tracker always stays with the built-in torrent client. The file selection on this page chooses the files here too: Real-Debrid and Debrid-Link fetch only those, and from the other services only those come here.',
