  'settings.modules.detail.torrentsOffDebrid': 'Вимкнено. Торренти, що вже йдуть, працюють далі й далі роздають. Нові йдуть до debrid-сервісу, що приймає торренти.',
  'collector.filtered.origin.account': 'акаунт debrid',
  'accounts.importAccount': 'Імпортувати з {account}',
  'accounts.importHint':
    'KnightLoader reads the service\'s list once a minute and brings in whatever was added there since you switched this on: torrents, and from TorBox and Premiumize.me also web and Usenet downloads. They land in the link collector like any other link and are fetched from this account. Nothing KnightLoader added itself comes in. The service does not say who added a download, so whatever another app adds with the same account comes in as well. Leave this off for an account that rdt-client or a second KnightLoader also uses. A download is deleted on the service once its files are here, or when you remove it here, unless "Keep downloads on the debrid service" is switched on under Settings, Torrents. A dash means the service has no list KnightLoader can read.',
  'settings.torrents.keepOnService': 'Залишати завантаження в debrid-сервісі',
  'settings.torrents.keepOnServiceHint': 'Коли вимкнено, KnightLoader видаляє торрент із debrid-сервісу, щойно всі його файли тут, і так само чинить із завантаженням, імпортованим з облікового запису, щоб там нічого не накопичувалося й не з’їдало ліміти облікового запису. Імпортоване завантаження, яке ви приберете тут до завершення, видаляється й там. Коли ввімкнено, обидва лишаються на сервісі, наприклад щоб пізніше відтворювати їх потоково просто звідти. Торрент, доданий KnightLoader, видаляється в будь-якому разі, якщо ви приберете його до завершення, а той, що вже був в обліковому записі, не видаляється ніколи.',
